const $=s=>document.querySelector(s), E=Engine;let timer=null,pending=null,session=0,active=false,state=null;
const games=[{id:'triple',name:'트리플 코드',tag:'논리력 · 추리력',desc:'세 가지 속성 속, 단 하나의 조합을 찾아보세요.',rules:['3×3의 9장 중 목표에 맞는 카드 3장을 선택합니다.','모양·개수·무늬는 속성별로 모두 같거나 모두 달라야 합니다. 각 문제의 목표를 확인하세요.','6라운드, 라운드당 40초. 정답은 100점 + 남은 초입니다.','오답은 누적 점수에서 30점 감점(최저 0점). 3회 오답 또는 시간초과 라운드는 0점입니다.']},{id:'memory',name:'기억의 짝',tag:'기억력 · 집중력',desc:'뒤집고 기억하고, 여덟 쌍의 연결을 완성하세요.',rules:['4×4 카드 16장, 총 8쌍을 찾습니다.','120초 안에 모든 짝을 찾으면 완료됩니다.','다른 두 카드는 1.2초 후 닫히며, 판정 중에는 입력할 수 없습니다.','점수 = max(0, 1000 − 5×경과초 − 40×오답). 미완료 경기는 최고점에서 제외합니다.']},{id:'chain',name:'숫자 연쇄',tag:'카드 · 전략',desc:'색과 숫자를 연결해 최고의 연쇄를 만드세요.',rules:['빨강·파랑·초록·노랑 1~9 카드 총 36장 중 시작 카드 1장과 선택 카드 3장을 받습니다.','선택 카드 1장을 카드줄의 왼쪽 또는 오른쪽 끝에 연결합니다. 같은 색이거나 숫자 차이가 정확히 1이면 연결 가능합니다.','성공한 배치는 2점, 숫자 차이 1이면 1점 추가입니다. 총 12번 배치할 수 있습니다.','연결 가능한 카드가 없을 때만 선택 카드 3장을 최대 2회 재추첨할 수 있습니다. 재추첨 시 기존 선택 카드는 버립니다.']},{id:'line',name:'라인 컨트롤',tag:'영역 · AI 전략',desc:'5×5 보드에서 AI보다 더 많은 직선을 확보하세요.',rules:['5×5 보드에서 나와 AI가 번갈아 한 칸씩 총 10번 돌을 놓습니다.','가로·세로·대각선으로 연속된 내 돌 3칸마다 3점을 얻습니다. 4칸 연속이면 서로 다른 3칸 구간 2개로 계산합니다.','종료 시 중앙 3×3에 놓인 내 돌 하나당 1점이 추가됩니다.','AI 난이도를 선택할 수 있습니다. 양쪽 10번씩 착수한 후 높은 점수가 승리합니다.']},{id:'nine',name:'나인 블러프',tag:'심리전 · 추리력',desc:'아홉 장의 카드, 일곱 번의 신중한 선택.',rules:['나와 AI가 각각 1~9 카드를 가지고 시작합니다.','7라운드, 각 20초. 카드를 골라 확정하면 동시에 공개합니다. 사용한 카드는 소모됩니다.','높은 숫자 1승점, 같은 숫자는 양쪽 0점입니다. 승점 → 승리한 숫자 차이 합 → 무승부 순으로 판정합니다.','시간초과 시 가장 낮은 카드 소모 및 상대 승리. 2회 연속 미제출은 기권입니다.']}];
$('#game-list').innerHTML=games.map(g=>`<article class="game-card ${g.id}"><button class="card-cover" onclick="tutorial('${g.id}')" aria-label="${g.name} 규칙과 시작"><img src="assets/${g.id==='chain'||g.id==='line'?g.id+'.svg':g.id+'-v2.png'}" alt="${g.name} 게임 이미지" width="326" height="130"></button><div class="card-body"><h3><button class="game-name" onclick="tutorial('${g.id}')">${g.name}</button></h3><div class="tags">${g.tag.split(' · ').map(t=>`<span>${t}</span>`).join('')}<span>싱글 1인</span></div><button class="card-play" onclick="tutorial('${g.id}')" aria-label="${g.name} 플레이"><span aria-hidden="true">→</span></button></div></article>`).join('');
function cleanup(){clearInterval(timer);clearTimeout(pending);timer=pending=null;session++;active=false}
function openModal(){if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){if(active&&!confirm('진행 중인 게임을 종료할까요? 완료하지 않은 경기는 저장되지 않습니다.'))return;cleanup();$('#modal').close()}
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
function info(title,message){cleanup();openModal();$('#content').innerHTML=`<h2>${title}</h2><p>${message}</p><button onclick="closeModal()">확인</button>`}
function tutorial(id){cleanup();let g=games.find(g=>g.id===id);openModal();$('#content').innerHTML=`<p class="eyebrow">HOW TO PLAY</p><h2>${g.name}</h2><p>${g.desc}</p><ol class="rules">${g.rules.map(x=>`<li>${x}</li>`).join('')}</ol>${(id==='nine'||id==='line')?'<label>AI 난이도 <select id="difficulty"><option value="easy">쉬움 · 무작위</option><option value="normal" selected>보통 · 이전 선택 분석</option><option value="hard">어려움 · 점수·남은 패 고려</option></select></label><br><br>':''}<button class="primary" onclick="start('${id}')">싱글플레이 시작 →</button><p class="note">중간 일시정지 없이 진행됩니다. 게임 기록은 이 브라우저에만 저장됩니다.</p>`}
function start(id){let difficulty=$('#difficulty')?.value||'normal';cleanup();active=true;if(id==='chain'||id==='line'){soloStart(id);return}if(id==='triple'){state={id,round:0,score:0,errors:0,log:[]};tripleRound()}else if(id==='memory'){state={id,deck:E.shuffle([...Array(8).keys(),...Array(8).keys()]),open:[],matched:[],errors:0,locked:false,start:Date.now()};memoryRender();clock(120,()=>finishMemory(false),()=>{$('#clock').textContent=remaining()})}else{state={id,difficulty,round:0,hand:[1,2,3,4,5,6,7,8,9],ai:[1,2,3,4,5,6,7,8,9],score:0,aiScore:0,gap:0,aiGap:0,timeouts:0,history:[],log:[]};nineRound()}}
function clock(seconds,expired,tick){clearInterval(timer);state.deadline=Date.now()+seconds*1000;let sid=session;timer=setInterval(()=>{if(sid!==session)return;tick();if(Date.now()>=state.deadline){clearInterval(timer);expired()}},100)}
function remaining(){return Math.max(0,Math.ceil((state.deadline-Date.now())/1000))}
function later(fn,ms=1200){let sid=session;pending=setTimeout(()=>{if(sid===session)fn()},ms)}
function tripleRound(){if(state.round===6){finish('트리플 코드',state.score,'6라운드 완료',true,state.log);return}state.round++;state.wrong=0;state.selection=[];state.puzzle=E.puzzle();state.locked=false;let labels=['모양','개수','무늬'];$('#content').innerHTML=`<h2>트리플 코드</h2><div class="status"><span>라운드 <strong>${state.round}/6</strong></span><span>남은 시간 <strong id="clock">40</strong>초</span><span>점수 <strong id="score">${state.score}</strong></span></div><div class="rules">목표: ${labels.map((x,i)=>`<b>${x}</b> ${state.puzzle.target[i]?'모두 같음':'모두 다름'}`).join(' · ')}</div><div class="board triple">${state.puzzle.cards.map((c,i)=>`<button class="tile" aria-label="${i+1}번 ${['원','삼각형','사각형'][c[0]]} ${c[1]+1}개 ${['빈 무늬','줄 무늬','채운 무늬'][c[2]]}" aria-pressed="false" onclick="selectTriple(${i})"><span style="color:${['#246cf0','#8952d8','#12877e'][c[0]]}">${['○','△','□'][c[0]].repeat(c[1]+1)}<small class="pattern">${['빈 무늬','줄 무늬','채운 무늬'][c[2]]}</small></span></button>`).join('')}</div><p class="message" id="message" role="status" aria-live="polite">카드 3장을 선택하세요.</p><button class="primary" id="submit" onclick="submitTriple()" disabled>정답 제출</button>`;clock(40,()=>tripleEnd(false,'시간초과'),()=>{$('#clock').textContent=remaining()})}
function selectTriple(i){if(state.locked)return;if(Date.now()>=state.deadline){tripleEnd(false,'시간초과');return}let a=state.selection;if(a.includes(i))a.splice(a.indexOf(i),1);else if(a.length<3)a.push(i);document.querySelectorAll('.triple .tile').forEach((el,j)=>{el.classList.toggle('selected',a.includes(j));el.setAttribute('aria-pressed',String(a.includes(j)))});$('#submit').disabled=a.length!==3}
function submitTriple(){if(state.locked||state.selection.length!==3)return;if(Date.now()>=state.deadline){tripleEnd(false,'시간초과');return}if(E.matches(state.puzzle.cards,state.selection,state.puzzle.target))tripleEnd(true,'정답');else{state.errors++;state.wrong++;state.score=Math.max(0,state.score-30);$('#score').textContent=state.score;$('#message').textContent=`오답입니다. −30점 · ${state.wrong}/3회`;if(state.wrong===3)tripleEnd(false,'3회 오답')}}
function tripleEnd(correct,reason){if(state.locked)return;state.locked=true;clearInterval(timer);let earned=correct?E.tripleScore(remaining()):0;state.score+=earned;state.log.push(`${state.round}라운드 · ${reason} · +${earned}점`);$('#score').textContent=state.score;$('#message').textContent=`${reason} · +${earned}점. 다음 라운드로 이동합니다.`;$('#submit').disabled=true;state.puzzle.answer.forEach(i=>document.querySelectorAll('.triple .tile')[i].classList.add('selected'));later(tripleRound,1500)}
const symbols=['🍎','🍋','🍇','🍒','🥝','🍊','🍓','🫐'];
function memoryRender(){ $('#content').innerHTML=`<h2>기억의 짝</h2><div class="status"><span>남은 시간 <strong id="clock">120</strong>초</span><span>찾은 짝 <strong id="pairs">0</strong>/8</span><span>오답 <strong id="errors">0</strong></span></div><div class="board memory">${state.deck.map((_,i)=>`<button class="tile" aria-label="${i+1}번 카드 뒤집기" onclick="flip(${i})">?</button>`).join('')}</div><p class="message" id="message" role="status" aria-live="polite">두 장씩 뒤집어 같은 과일을 찾아보세요.</p>`}
function flip(i){if(state.locked||state.matched.includes(i)||state.open.includes(i))return;if(Date.now()>=state.deadline){finishMemory(false);return}let el=document.querySelectorAll('.memory .tile')[i];el.textContent=symbols[state.deck[i]];el.classList.add('open');el.setAttribute('aria-label',`${i+1}번 ${symbols[state.deck[i]]}`);state.open.push(i);if(state.open.length===2){state.locked=true;let [a,b]=state.open;if(state.deck[a]===state.deck[b]){state.matched.push(a,b);[a,b].forEach(j=>{let c=document.querySelectorAll('.memory .tile')[j];c.classList.add('matched');c.disabled=true});$('#pairs').textContent=state.matched.length/2;state.open=[];state.locked=false;if(state.matched.length===16)finishMemory(true)}else{state.errors++;$('#errors').textContent=state.errors;later(()=>{[a,b].forEach(j=>{let c=document.querySelectorAll('.memory .tile')[j];c.textContent='?';c.classList.remove('open');c.setAttribute('aria-label',`${j+1}번 카드 뒤집기`)});state.open=[];state.locked=false},1200)}}}
function finishMemory(complete){if(!active)return;let elapsed=Math.min(120,Math.floor((Date.now()-state.start)/1000));finish('기억의 짝',complete?E.memoryScore(elapsed,state.errors):0,complete?'8쌍 모두 찾았어요!':'시간초과 · 미완료',complete,[`경과 ${elapsed}초 · 오답 ${state.errors}회`,`찾은 짝 ${state.matched.length/2}/8`])}
function chooseAI(){let hand=state.ai;if(state.difficulty==='easy'||!state.history.length)return E.shuffle(hand)[0];let avg=state.history.reduce((a,b)=>a+b,0)/state.history.length;let target=state.difficulty==='hard'?(state.score<state.aiScore?avg:avg+1):avg+Math.random()*2;return [...hand].sort((a,b)=>Math.abs(a-target)-Math.abs(b-target))[0]}
function nineRound(){if(state.round===7){nineFinish();return}state.round++;state.selection=null;state.locked=false;state.aiChoice=chooseAI();$('#content').innerHTML=`<h2>나인 블러프</h2><div class="status"><span>라운드 <strong>${state.round}/7</strong></span><span>남은 시간 <strong id="clock">20</strong>초</span><span>나 <strong>${state.score}</strong> : AI <strong>${state.aiScore}</strong></span></div><div class="arena"><div><small>나의 선택</small><strong id="mine">?</strong></div><span>VS</span><div><small>AI · 선택 완료</small><strong id="opponent">?</strong></div></div><div class="hand">${state.hand.map(n=>`<button aria-pressed="false" onclick="selectNine(${n},this)">${n}</button>`).join('')}</div><p class="message" id="message" role="status" aria-live="polite">사용할 카드를 고른 뒤 확정하세요.</p><button class="primary" id="submit" disabled onclick="revealNine(false)">선택 확정 · 동시 공개</button><p class="note">AI 남은 카드: ${[...state.ai].sort((a,b)=>a-b).join(', ')} · 연속 미제출 ${state.timeouts}/2</p>`;clock(20,()=>revealNine(true),()=>$('#clock').textContent=remaining())}
function selectNine(n,el){if(state.locked)return;if(Date.now()>=state.deadline){revealNine(true);return}state.selection=n;document.querySelectorAll('.hand button').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});el.classList.add('selected');el.setAttribute('aria-pressed','true');$('#mine').textContent=n;$('#submit').disabled=false}
function revealNine(timeout){if(state.locked)return;timeout=timeout||Date.now()>=state.deadline;if(!timeout&&state.selection===null)return;state.locked=true;clearInterval(timer);let a=timeout?Math.min(...state.hand):state.selection,b=state.aiChoice;state.hand=state.hand.filter(n=>n!==a);state.ai=state.ai.filter(n=>n!==b);state.timeouts=timeout?state.timeouts+1:0;if(!timeout)state.history.push(a);let result=E.bluff(a,b,timeout,false);state.score+=result.a;state.aiScore+=result.b;state.gap+=result.gapA;state.aiGap+=result.gapB;let text=timeout?'미제출 · AI 승리':a>b?'이번 라운드 승리':a<b?'이번 라운드 패배':'같은 숫자 · 무득점';state.log.push(`${state.round}라운드 · 나 ${a} / AI ${b} · ${text}`);$('#mine').textContent=a;$('#opponent').textContent=b;$('#message').textContent=text;$('#submit').disabled=true;later(()=>{if(state.timeouts>=2)nineFinish(true);else nineRound()},1700)}
function nineFinish(forfeit=false){let cmp=state.score-state.aiScore||state.gap-state.aiGap;let title=forfeit?'2회 연속 미제출 · 기권':cmp>0?'승리!':cmp<0?'AI 승리':'무승부';finish('나인 블러프',state.score,title,!forfeit,[`나 ${state.score} : AI ${state.aiScore} · 숫자 차이 합 ${state.gap} : ${state.aiGap}`,...state.log])}
function readRecords(){try{let a=JSON.parse(localStorage.getItem('panludiq.records.v1')||'[]');return Array.isArray(a)?a.filter(x=>games.some(g=>g.id===x.id)&&Number.isFinite(x.score)&&typeof x.time==='string').slice(0,100):[]}catch{return []}}
function finish(name,score,message,complete,log){let id=state.id;cleanup();let saved=true;try{let rows=readRecords();rows.unshift({id,score,complete,message,time:new Date().toISOString()});localStorage.setItem('panludiq.records.v1',JSON.stringify(rows.slice(0,100)))}catch{saved=false}$('#content').innerHTML=`<div class="result"><p class="eyebrow">GAME RESULT</p><h2>${name} · ${message}</h2><div class="score">${score}<small>${id==='nine'?'승점':'점'}</small></div><p class="note">${saved?'이 브라우저에 기록을 저장했습니다.':'브라우저 저장 공간을 사용할 수 없어 기록을 저장하지 못했습니다.'}</p></div><div class="rules">${log.map(x=>`<div>${x}</div>`).join('')}</div><div class="actions"><button class="primary" onclick="tutorial('${id}')">다시 플레이</button><button onclick="showRecords()">내 기록</button><button onclick="closeModal()">홈으로</button></div>`}
function showRecords(){cleanup();openModal();let rows=readRecords();$('#content').innerHTML=`<h2>내 기록</h2><p class="note">이 브라우저의 경기만 표시합니다. 공용 랭킹과 계정 동기화는 준비 중입니다.</p><div class="rules">${games.map(g=>{let scores=rows.filter(r=>r.id===g.id&&r.complete).map(r=>r.score);return `<div>${g.name} · 최고 ${scores.length?Math.max(...scores)+(g.id==='nine'?'승점':'점'):'기록 없음'}</div>`}).join('')}</div><h3>최근 경기</h3>${rows.length?rows.slice(0,20).map(r=>`<div class="record-row"><span>${games.find(g=>g.id===r.id).name}<small><br>${new Date(r.time).toLocaleString('ko-KR')}</small></span><strong>${r.score}${r.id==='nine'?'승점':'점'}${r.complete?'':' · 미완료'}</strong></div>`).join(''):'<div class="empty">첫 번째 게임을 시작해보세요.</div>'}<button style="margin-top:20px" onclick="clearRecords()" ${rows.length?'':'disabled'}>내 기록 지우기</button>`}
function clearRecords(){if(!confirm('이 브라우저의 판루딕 기록을 모두 지울까요?'))return;try{localStorage.removeItem('panludiq.records.v1');showRecords()}catch{info('삭제 실패','브라우저 저장소 접근이 제한되어 있습니다.')}}
